import json,re,math
txt=re.sub(r'\x1b\[[0-9;]*m','',open('results/run60/train.log',errors='replace').read())
rows={}
for m in re.finditer(r'step:(\d+) - (.*)',txt):
    s=int(m.group(1)); d={}
    for kv in m.group(2).split(' - '):
        if ':' in kv:
            k,v=kv.split(':',1); d[k]=v
    rows[s]=d
def f(d,k):
    try: return float(d[k])
    except: return None
tr=[(s,f(d,'critic/score/mean')) for s,d in rows.items() if f(d,'critic/score/mean') is not None]
va=[(s,f(d,'val-core/openai/gsm8k/acc/mean@1')) for s,d in rows.items() if f(d,'val-core/openai/gsm8k/acc/mean@1') is not None]
def reg(pairs):
    xs=[a for a,_ in pairs]; ys=[b for _,b in pairs]; n=len(xs)
    mx=sum(xs)/n; my=sum(ys)/n
    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    b=sxy/sxx; a=my-b*mx
    sse=sum((y-(a+b*x))**2 for x,y in zip(xs,ys)); se=math.sqrt(sse/(n-2)/sxx)
    return b, b/se, a, my
for name,p in [('train reward',tr),('val acc',va)]:
    b,t,a,my=reg(p)
    print(f'{name}: n={len(p)} mean={my:.4f} slope={b:+.6f}/step t={t:+.2f} fitted_end-start={b*(p[-1][0]-p[0][0]):+.4f}')
print('train reward first/last', tr[0], tr[-1])
print('vals', [(s,round(v,4)) for s,v in va])
EOF

